const toggle = document.querySelector('#toggle-guide');
const guide = document.querySelector('#loan-guide');

toggle.addEventListener('click', () => {
  guide.hidden = !guide.hidden;
  toggle.setAttribute('aria-expanded', String(guide.hidden));
});

const generate = document.querySelector('#generate-receipt');
const receipt = document.querySelector('#receipt-status');

function showReceipt() {
  receipt.textContent = 'receipt has been generated';
  generate.disabled = false;
}

generate.addEventListener('click', () => {
  receipt.textContent = 'Generating receipt';
  generate.disabled = true;
  showReceipt();
});

const start = document.querySelector('#start-sampling');
const stop = document.querySelector('#stop-sampling');
const status = document.querySelector('#sampling-status');
const log = document.querySelector('#sample-log');
let timerId;

function recordSample() {
  const entry = document.createElement('li');
  entry.textContent = 'No. ' + (log.children.length + 1) + ' samples';
  log.append(entry);
  status.textContent = 'is sampling';
}

start.addEventListener('click', () => {
  status.textContent = 'is sampling';
  start.disabled = true;
  stop.disabled = false;
  timerId = setInterval(recordSample, 200);
});

stop.addEventListener('click', () => {
  status.textContent = 'Sampling has stopped';
  start.disabled = false;
  stop.disabled = true;
});

const nicknameInput = document.querySelector('#nickname');
const save = document.querySelector('#save-name');
const savedName = document.querySelector('#saved-name');
const storageKey = 'visitorNickname';

save.addEventListener('click', () => {
  const nickname = nicknameInput.value.trim();
  if (!nickname) return;

  localStorage.setItem(storageKey, nickname);
  savedName.textContent = nickname;
});

const gearInput = document.querySelector('#gear-item');
const add = document.querySelector('#add-gear');
const list = document.querySelector('#gear-list');
const empty = document.querySelector('#gear-empty');
const storageKey = 'fieldGear';
const items = JSON.parse(localStorage.getItem(storageKey) ?? '[]');

function renderList() {
  list.replaceChildren();
  for (const item of items) {
    const row = document.createElement('li');
    row.textContent = item;
    list.append(row);
  }
  empty.hidden = items.length > 0;
}

add.addEventListener('click', () => {
  const item = gearInput.value.trim();
  if (!item) return;

  items.push(item);
  localStorage.setItem(storageKey, items);
  gearInput.value = '';
  renderList();
});

renderList();
